/* =====================================================================
   PROYECTO: Análisis de Trade Marketing (SQL Server)
   SCRIPT 02: Carga de datos SIMULADOS en las 4 tablas (ejecutar después del 01)
   ---------------------------------------------------------------------
   Ejecutar UNA SOLA VEZ, con las 4 tablas ya creadas y vacías.
   Los datos son ficticios (simulados). Se generaron una sola vez y
   quedaron escritos tal cual, así que los resultados siempre son los mismos.
   Resultado: 24 vendedores, 30 productos, 5.000 ventas, 1.500 auditorías.
   ===================================================================== */

USE trade_marketing;
GO

/* ---------------------------------------------------------------------
   PROTECCIÓN: si las tablas ya tienen datos, el script se detiene aquí
   para no duplicarlos. Para empezar de cero, ejecuta primero
   01_crear_tablas.sql (borra y vuelve a crear las tablas vacías).
--------------------------------------------------------------------- */
IF EXISTS (SELECT 1 FROM vendedores)
BEGIN
    RAISERROR('Las tablas ya tienen datos. Ejecuta primero 01_crear_tablas.sql para empezar de cero.', 16, 1);
    RETURN;
END

