/* =====================================================================
   5. VERIFICACIÓN: cuántas filas quedaron en cada tabla
   Esperado: 24 | 30 | 5000 | 1500
   ===================================================================== */
SELECT 'vendedores'    AS tabla, COUNT(*) AS filas FROM vendedores
UNION ALL
SELECT 'productos',               COUNT(*)          FROM productos
UNION ALL
SELECT 'ventas',                  COUNT(*)          FROM ventas
UNION ALL
SELECT 'auditoria_pdv',           COUNT(*)          FROM auditoria_pdv;
